    "83127efc": {"text":"Die Schuld eines Willkommens","hash":"h1-2e4826c9"},
    "83134ac7": {"text":"Zitieren Sie Brauch gegen seine Bilanz.","hash":"h1-5904bf8b"},
    "8327f969": {"text":"Kosten {money:10}.","hash":"h1-5307d525"},
