    "cfbe92ad": {"text":"Der Handwerksgilde beigetreten.","hash":"h1-7f700bf4"},
    "cfc71515": {"text":"Münze hält; geliehenes Eisen nicht. Reisen Sie mit leichtem Gepäck.","hash":"h1-796d5c65"},
    "cfcabaa2": {"text":"Küstenlotsen","hash":"h1-7a1916a6"},
    "cfcd235d": {"text":"de jure","hash":"h1-5688c86a"},
