    "e308dfda": {"text":"Lehnen: {name}","hash":"h1-3ac5b0f0"},
    "e30af0e5": {"text":"Hausierer","hash":"h1-1036acbd"},
    "e319bc76": {"text":"Die Münzprägung entwerten?","hash":"h1-5f0bf819"},
    "e31a7b78": {"text":"Beurteilen Sie es selbst, fair.","hash":"h1-3505e83f"},
    "e31f0452": {"text":"Keine – dieses Land ernährt kein Herzogtum oder keine Krone.","hash":"h1-f5bed8f1"},
    "e3204428": {"text":"Vermittelt den Kredit und die Geschäfte des Haushalts über Markt- und Gildenverbindungen.","hash":"h1-d55f5d9f"},
    "e320b451": {"text":"Barqa","hash":"h1-a5976240"},
    "e320d732": {"text":"Speere – Sie müssen reiten oder teuer bezahlen","hash":"h1-6b99a5c9"},
    "e3256bb5": {"text":"Moschee","hash":"h1-06bbe407"},
